def specified_element(nums, n):
    """The program dawnr proved in `t`, written in Python (checked against `t`, not itself proved).

    requires n >= 0
    requires forall i in [0, len(nums)) . n < len(nums[i])
    ensures  len(r) == len(nums)
    ensures  forall i in [0, len(nums)) . r[i] == nums[i][n]

    Outside its `requires` it raises ValueError: nothing was proved there.
    """
    if not (_t_ints(nums, 2)):
        raise TypeError('specified_element: `nums` must be a list of lists of integers; nothing was proved for anything else')
    if not (_t_ints(n, 0)):
        raise TypeError('specified_element: `n` must be an integer; nothing was proved for anything else')
    nums = _t_tuple(nums)
    if not _t_requires(nums, n):
        raise ValueError('specified_element: this input is outside what was proved (requires n >= 0; forall i in [0, len(nums)) . n < len(nums[i]))')
    _t_result = _t_core(nums, n)
    return _t_list(_t_result)

def _t_core(nums, n):
    r = ()
    i = 0
    # invariant: 0 <= i
    # invariant: i <= len(nums)
    # invariant: len(r) == i
    # invariant: forall j in [0, i) . r[j] == nums[j][n]
    # decreases: len(nums) - i
    while (i < len(nums)):
        r = (r + (nums[i][n], ))
        i = (i + 1)
    return r

def _t_requires(nums, n):
    try:
        return bool((n >= 0)) and bool(all((n < len(nums[i])) for i in range(0, len(nums))))
    except (IndexError, ZeroDivisionError):   # a `requires` with no value here admits nothing
        return False

def _t_tuple(v):
    return tuple(_t_tuple(x) for x in v) if isinstance(v, (list, tuple)) else v

def _t_ints(v, depth):
    if depth == 0:
        return isinstance(v, int) and not isinstance(v, bool)
    return isinstance(v, (list, tuple)) and all(_t_ints(x, depth - 1) for x in v)

def _t_list(v):
    return [_t_list(x) for x in v] if isinstance(v, tuple) else v

